void Interface::drawEnergyRoutes(){
 float tile=38*factoryZoom;if(tile<6)return;double clock=factory.tick+(factory.running?factoryAccumulator/.55:0);
 auto portAt=[&](Position p,EnergyMedium medium,int direction){auto m=factory.at(p);if(!m||!isEnergyMachine(m->kind))return false;for(auto port:energyPorts(*m))if(port.medium==medium&&port.direction==direction)return true;return false;};
 for(const auto& [p,links]:factory.energyLinks){auto full=factoryTile(p);if(!CheckCollisionRecs(full,factoryView))continue;for(const auto& link:links){bool focus=energyLinkSelected&&selectedEnergyMedium==link.medium;float offset=(-.33f+float(int(link.medium)%5)*.12f)*tile;Vector2 c{full.x+tile*.5f,full.y+tile*.5f+offset};Color color=energyColor(link.medium);float alpha=link.enabled&&!link.tripped?(floorFlow?.65f:.35f):.16f;float thickness=std::max(1.2f,tile*(focus?.09f:.045f));int count=0;
  for(int d=0;d<4;d++){Position q=nextPosition(p,d);auto neighbor=factory.energyLink(q,link.medium);if(!neighbor&&!portAt(q,link.medium,(d+2)%4))continue;count++;auto delta=directions[d];Vector2 end{c.x+delta[0]*tile*.5f,c.y+delta[1]*tile*.5f};DrawLineEx(c,end,thickness+1,Fade(Color{51,68,70,255},alpha*.5f));DrawLineEx(c,end,thickness,Fade(color,alpha));if(link.medium==EnergyMedium::Shaft&&tile>=22){Vector2 mid{(c.x+end.x)*.5f,(c.y+end.y)*.5f};DrawLineEx({mid.x-delta[1]*tile*.06f,mid.y+delta[0]*tile*.06f},{mid.x+delta[1]*tile*.06f,mid.y-delta[0]*tile*.06f},1.1f,Fade(color,alpha));}}
  if(count>2||count==0)DrawCircleV(c,std::max(1.8f,thickness),Fade(color,alpha));
  if(floorFlow&&link.enabled&&!link.tripped&&link.flow>.001){auto delta=directions[link.dir];double phase=std::fmod(clock*(.7+std::min(1.,link.flow/link.rating)),1.);float t=float(phase)-.5f;Vector2 a{c.x+delta[0]*tile*(t-.16f),c.y+delta[1]*tile*(t-.16f)},b{c.x+delta[0]*tile*(t+.16f),c.y+delta[1]*tile*(t+.16f)};DrawLineEx(a,b,thickness+1.2f,Fade(color,.95f));}
  if(link.tripped||link.heat>.65){DrawCircleV(c,std::max(2.f,tile*.06f),Color{235,83,49,255});if(tile>=35)text(link.tripped?"TRIP":"HOT",c.x+3,c.y-9,7,Color{203,64,42,255},true);}
 }}
}
